import datetime as _dt

_TZB = {}
_TZC = {}


def _et(ts):
    """(ET day ordinal, ET minute of day) from a UTC ISO timestamp."""
    k = ts[:13]
    v = _TZC.get(k)
    if v is None:
        u = _dt.datetime(int(ts[0:4]), int(ts[5:7]), int(ts[8:10]), int(ts[11:13]))
        y = u.year
        b = _TZB.get(y)
        if b is None:
            d = _dt.date(y, 3, 1)
            s = _dt.datetime(y, 3, 1 + (6 - d.weekday()) % 7 + 7, 7, 0)
            d2 = _dt.date(y, 11, 1)
            e = _dt.datetime(y, 11, 1 + (6 - d2.weekday()) % 7, 6, 0)
            b = _TZB[y] = (s, e)
        x = u - _dt.timedelta(hours=(4 if b[0] <= u < b[1] else 5))
        v = _TZC[k] = (x.toordinal(), x.hour * 60)
    return v[0], v[1] + int(ts[14:16])


def _wilder_atr(h, l, c, period):
    n = len(c)
    out = [None] * n
    prev_c = None
    acc = 0.0
    for i in range(n):
        tr = (h[i] - l[i]) if prev_c is None else max(
            h[i] - l[i], abs(h[i] - prev_c), abs(l[i] - prev_c))
        prev_c = c[i]
        if i < period:
            acc += tr
            if i == period - 1:
                out[i] = acc / period
        else:
            out[i] = (out[i - 1] * (period - 1) + tr) / period
    return out


def _median(xs):
    s = sorted(xs)
    n = len(s)
    return s[n // 2] if n % 2 else 0.5 * (s[n // 2 - 1] + s[n // 2])


def family_init(ctx):
    bars = ctx.bars
    n = len(bars)
    c = [float(b["c"]) for b in bars]
    h = [float(b["h"]) for b in bars]
    l = [float(b["l"]) for b in bars]
    per = max(2, int(ctx.p.kg_atr))
    atr = _wilder_atr(h, l, c, per)
    mult = float(ctx.p.kg_mult)
    med_n = max(2, int(ctx.p.kg_med))
    shallow = int(ctx.p.kg_shallow)

    entry = [0] * n
    flip = [0] * n

    R = None
    day = None
    dr = 0                 # direction the kagi line is currently drawing
    ext = None             # its running extreme close
    shoulder = None        # last high where the line turned down
    waist = None           # last low where it turned up
    state = 0              # +1 yang (thick), -1 yin (thin)
    swings = []            # completed swing lengths, oldest first
    dn_i = -1              # index in swings of the last completed DOWN swing
    up_i = -1

    for i in range(n):
        a = atr[i]
        if a is None or a <= 0:
            continue
        d, m = _et(bars[i]["t"])
        # the reversal amount is set at the open and held for the session
        if R is None or (d != day and m >= 570):
            R = mult * a
            day = d
        p = c[i]
        if dr == 0:
            dr, ext = 1, p
            continue

        if dr > 0:
            if p > ext:
                ext = p
            elif p <= ext - R:
                if waist is not None:
                    swings.append(abs(ext - waist))
                    up_i = len(swings) - 1
                shoulder = ext
                dr, ext = -1, p
        else:
            if p < ext:
                ext = p
            elif p >= ext + R:
                if shoulder is not None:
                    swings.append(abs(shoulder - ext))
                    dn_i = len(swings) - 1
                waist = ext
                dr, ext = 1, p

        # thickness: yang once above the last shoulder, yin once below the
        # last waist, and it persists until the opposite condition fires
        ns = state
        if shoulder is not None and p > shoulder:
            ns = 1
        elif waist is not None and p < waist:
            ns = -1
        if ns != state:
            if state != 0:
                flip[i] = ns
                ok = True
                if shallow:
                    ok = False
                    j = dn_i if ns > 0 else up_i
                    if j >= 0:
                        hist = swings[max(0, j - med_n):j]
                        if len(hist) >= 3 and swings[j] < _median(hist):
                            ok = True
                if ok:
                    entry[i] = ns
            state = ns

    ctx.kg_entry = ctx.series(entry, "kagi_entry")
    ctx.kg_flip = ctx.series(flip, "kagi_flip")


def signal(ctx, i):
    s = ctx.kg_entry[i]
    return s if s else 0


def exit_signal(ctx, i):
    f = ctx.kg_flip[i]
    if not f or not ctx.positions:
        return False
    long_side = ctx.positions[0]["side"] == "long"
    return (f < 0) if long_side else (f > 0)
